'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var beta = require( '@stdlib/math/base/special/beta' );
var PINF = require( '@stdlib/constants/float64/pinf' );


// MAIN //

/**
* Returns the expected value of a Burr (type III) distribution with first shape parameter `c` and second shape parameter `d`.
*
* @param {PositiveNumber} c - first shape parameter
* @param {PositiveNumber} d - second shape parameter
* @returns {PositiveNumber} expected value
*
* @example
* var y = mean( 2.0, 1.0 );
* // returns ~1.571
*
* @example
* var y = mean( 4.0, 12.0 );
* // returns ~2.263
*
* @example
* var y = mean( 8.0, 2.0 );
* // returns ~1.154
*
* @example
* var y = mean( 1.0, 2.0 );
* // returns Infinity
*
* @example
* var y = mean( NaN, 2.0 );
* // returns NaN
*
* @example
* var y = mean( 2.0, NaN );
* // returns NaN
*
* @example
* var y = mean( -1.0, 2.0 );
* // returns NaN
*
* @example
* var y = mean( 2.0, -1.0 );
* // returns NaN
*/
function mean( c, d ) {
	if (
		isnan( c ) ||
		isnan( d ) ||
		c <= 0.0 ||
		d <= 0.0
	) {
		return NaN;
	}
	if ( c <= 1.0 ) {
		return PINF;
	}
	return d * beta( d + ( 1.0 / c ), 1.0 - ( 1.0 / c ) );
}


// EXPORTS //

module.exports = mean;
